const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sakurajima = ee.Geometry.Point(130.658, 31.584); // Approximate coordinates for Sakurajima volcano
  const buffer = sakurajima.buffer(5000); // 5km buffer around the volcano to get average wind

  const startDate = '2015-05-21T00:00:00';
  const endDate = '2015-05-21T12:00:00'; // Analyze wind for 12 hours after the eruption

  const pressureLevel = 850; // hPa - represents lower troposphere winds, typically influencing ash dispersion

  // 2. Data Acquisition & Check
  let era5 = ee.ImageCollection('ECMWF/ERA5/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(sakurajima)
    .select(['u_component_of_wind', 'v_component_of_wind'], ['u', 'v']) // Rename bands for convenience
    .filter(ee.Filter.eq('pressure_level', pressureLevel));

  const collectionSize = await era5.size().getInfo();
  if (collectionSize === 0) {
    console.log("No ERA5 data found for the specified date, location, and pressure level.");
    console.log("C1");
    return;
  }

  // 3. Processing & Calculation
  const windDirections = await Promise.all(
    era5.map(async (image) => {
      const time = image.get('system:time_start');
      const time_str = new Date(time.getInfo()).toUTCString();

      const reduced = await image.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: buffer,
        scale: 27830, // ERA5 resolution is ~27km, use a scale larger than that
        maxPixels: 1e9,
        tileScale: 4
      }).getInfo();

      const u = reduced.u;
      const v = reduced.v;

      // Check for C3 (Calculation Failure: None/NaN values)
      if (u === null || v === null || isNaN(u) || isNaN(v)) {
        return { time: time_str, status: 'C3' };
      }

      // Wind direction logic for ash dispersion (where the wind is blowing TO)
      // Positive u: Eastward component. Positive v: Northward component.
      let primaryDirection = '';
      let secondaryDirection = '';

      if (u > 0.5) { // Threshold to consider significant eastward push
        primaryDirection += 'east';
      } else if (u < -0.5) { // Threshold to consider significant westward push
        primaryDirection += 'west';
      }

      if (v < -0.5) { // Threshold to consider significant southward push
        secondaryDirection += 'south';
      } else if (v > 0.5) { // Threshold to consider significant northward push
        secondaryDirection += 'north';
      }

      // If no significant component, it's calm or complex, or primarily N/S or E/W
      if (primaryDirection === '' && secondaryDirection === '') {
        return { time: time_str, direction: 'Calm or No Dominant Direction', u: u, v: v };
      }

      return { time: time_str, direction: `${primaryDirection} ${secondaryDirection}`.trim(), u: u, v: v };

    }).map(async (f) => await f)
  ); // Using Promise.all with async map to handle inner getInfo() calls

  let firstEastThenSouth = false;
  let firstSouthThenEast = false;
  let hasValidWindData = false;

  console.log("Hourly Wind Directions (Ash Dispersion):");
  let hourlyDirections = [];

  for (const result of windDirections) {
    if (result.status === 'C3') {
      console.log(`Calculation Failure for ${result.time}: C3`);
      console.log("C3");
      return;
    }
    if (result.direction) {
      console.log(`- ${result.time}: ${result.direction} (u: ${result.u.toFixed(2)} m/s, v: ${result.v.toFixed(2)} m/s)`);
      hourlyDirections.push(result.direction);
      hasValidWindData = true;
    }
  }

  if (!hasValidWindData) {
    console.log("No valid wind direction data could be retrieved after processing.");
    console.log("C2"); // Or C3 if it was specifically due to NaN/null in results
    return;
  }

  // Analyze the sequence of directions
  let eastComponentFound = false;
  let southComponentFound = false;

  for (const dir of hourlyDirections) {
    const isEast = dir.includes('east');
    const isSouth = dir.includes('south');

    if (isEast && !southComponentFound) {
      eastComponentFound = true;
    }
    if (isSouth && eastComponentFound) {
      firstEastThenSouth = true;
      break; // Found the sequence
    }
  }

  // Reset for the other sequence
  eastComponentFound = false;
  southComponentFound = false;

  for (const dir of hourlyDirections) {
    const isEast = dir.includes('east');
    const isSouth = dir.includes('south');

    if (isSouth && !eastComponentFound) {
      southComponentFound = true;
    }
    if (isEast && southComponentFound) {
      firstSouthThenEast = true;
      break; // Found the sequence
    }
  }

  console.log(`Sequence "first east then south": ${firstEastThenSouth}`);
  console.log(`Sequence "first south then east": ${firstSouthThenEast}`);

  // 5. Validation & Final Answer
  if (firstEastThenSouth && !firstSouthThenEast) {
    console.log("A");
  } else if (!firstEastThenSouth && firstSouthThenEast) {
    console.log("B");
  } else if (firstEastThenSouth && firstSouthThenEast) {
    console.log("Both sequences observed, or ambiguous.");
    console.log("B"); // If both happen, the premise "rather than" is not exclusively true
  }
  else {
    console.log("Neither sequence observed clearly, or data inconclusive.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
